Here is a production-ready `.jsx` ExtendScript for Adobe InDesign that:

- takes the active spread/facing-pages document
- creates a new single-page document
- preserves page size, margins, guides, layers, and page order
- recreates master pages as single-page masters
- keeps document pages linked to equivalent master pages
- duplicates page items in place so layout/positioning stays intact

It is written to be reasonably fast and safe for large documents.

## Script

Save as something like:

`ConvertSpreadsToSinglePages.jsx`

```jsx
#target "InDesign"

(function () {
    if (app.documents.length === 0) {
        alert("Open a document first.");
        return;
    }

    var src = app.activeDocument;
    var oldUI = app.scriptPreferences.userInteractionLevel;
    var oldRedraw = app.scriptPreferences.enableRedraw;

    try {
        app.scriptPreferences.userInteractionLevel = UserInteractionLevels.NEVER_INTERACT;
        app.scriptPreferences.enableRedraw = false;

        app.doScript(function () {
            main(src);
        }, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "Convert spreads document to single-page document");
    } catch (e) {
        alert("Error: " + e);
    } finally {
        app.scriptPreferences.userInteractionLevel = oldUI;
        app.scriptPreferences.enableRedraw = oldRedraw;
    }

    function main(srcDoc) {
        // -----------------------------
        // Preserve measurement/ruler setup
        // -----------------------------
        var srcHMU = srcDoc.viewPreferences.horizontalMeasurementUnits;
        var srcVMU = srcDoc.viewPreferences.verticalMeasurementUnits;
        var srcRO = srcDoc.viewPreferences.rulerOrigin;
        var srcZP = srcDoc.zeroPoint;

        srcDoc.viewPreferences.horizontalMeasurementUnits = MeasurementUnits.POINTS;
        srcDoc.viewPreferences.verticalMeasurementUnits = MeasurementUnits.POINTS;
        srcDoc.viewPreferences.rulerOrigin = RulerOrigin.PAGE_ORIGIN;
        srcDoc.zeroPoint = [0, 0];

        // -----------------------------
        // Create destination document
        // -----------------------------
        var dst = app.documents.add();
        dst.documentPreferences.facingPages = false;
        dst.documentPreferences.pageWidth = srcDoc.documentPreferences.pageWidth;
        dst.documentPreferences.pageHeight = srcDoc.documentPreferences.pageHeight;
        dst.documentPreferences.pagesPerDocument = 1;

        // Copy bleed/slug
        copyDocumentPreferences(srcDoc, dst);

        // Match measurement/ruler setup
        dst.viewPreferences.horizontalMeasurementUnits = MeasurementUnits.POINTS;
        dst.viewPreferences.verticalMeasurementUnits = MeasurementUnits.POINTS;
        dst.viewPreferences.rulerOrigin = RulerOrigin.PAGE_ORIGIN;
        dst.zeroPoint = [0, 0];

        // -----------------------------
        // Copy layers first
        // -----------------------------
        syncLayers(srcDoc, dst);

        // -----------------------------
        // Rebuild masters as single-page masters
        // key = srcMaster.id + "_" + sideCode
        // -----------------------------
        var masterMap = buildSinglePageMasters(srcDoc, dst);

        // Remove default destination master if unused later
        var defaultMaster = null;
        try {
            defaultMaster = dst.masterSpreads[0];
        } catch (_) {}

        // -----------------------------
        // Build destination page count
        // -----------------------------
        while (dst.pages.length < srcDoc.pages.length) {
            dst.pages.add();
        }

        // -----------------------------
        // Copy page-by-page
        // -----------------------------
        var srcPages = srcDoc.pages.everyItem().getElements();
        var i, j;

        for (i = 0; i < srcPages.length; i++) {
            var sp = srcPages[i];
            var dp = dst.pages[i];

            // Page size
            copyPageSize(sp, dp);

            // Margins and columns
            copyMarginPreferences(sp, dp);

            // Applied master
            applyEquivalentMaster(sp, dp, masterMap);

            // Page guides
            copyGuides(sp, dp);

            // Duplicate local page items only
            var pageItems = sp.pageItems.everyItem().getElements();
            for (j = 0; j < pageItems.length; j++) {
                duplicateItemSafely(pageItems[j], dp, dst);
            }
        }

        // Try deleting initial default master if not used
        tryDeleteUnusedDefaultMaster(defaultMaster, dst);

        // Restore source doc prefs
        srcDoc.viewPreferences.horizontalMeasurementUnits = srcHMU;
        srcDoc.viewPreferences.verticalMeasurementUnits = srcVMU;
        srcDoc.viewPreferences.rulerOrigin = srcRO;
        srcDoc.zeroPoint = srcZP;

        alert("Done.\nCreated single-page version: " + dst.name);
    }

    function copyDocumentPreferences(srcDoc, dstDoc) {
        try {
            dstDoc.documentPreferences.pageOrientation = srcDoc.documentPreferences.pageOrientation;
        } catch (_) {}

        try {
            dstDoc.documentPreferences.documentBleedTopOffset = srcDoc.documentPreferences.documentBleedTopOffset;
            dstDoc.documentPreferences.documentBleedBottomOffset = srcDoc.documentPreferences.documentBleedBottomOffset;
            dstDoc.documentPreferences.documentBleedInsideOrLeftOffset = srcDoc.documentPreferences.documentBleedInsideOrLeftOffset;
            dstDoc.documentPreferences.documentBleedOutsideOrRightOffset = srcDoc.documentPreferences.documentBleedOutsideOrRightOffset;
            dstDoc.documentPreferences.documentBleedUniformSize = srcDoc.documentPreferences.documentBleedUniformSize;
        } catch (_) {}

        try {
            dstDoc.documentPreferences.slugTopOffset = srcDoc.documentPreferences.slugTopOffset;
            dstDoc.documentPreferences.slugBottomOffset = srcDoc.documentPreferences.slugBottomOffset;
            dstDoc.documentPreferences.slugInsideOrLeftOffset = srcDoc.documentPreferences.slugInsideOrLeftOffset;
            dstDoc.documentPreferences.slugRightOrOutsideOffset = srcDoc.documentPreferences.slugRightOrOutsideOffset;
        } catch (_) {}

        try {
            dstDoc.documentPreferences.intent = srcDoc.documentPreferences.intent;
        } catch (_) {}
    }

    function syncLayers(srcDoc, dstDoc) {
        var i;
        // Remove default layer if possible later
        var defaultLayer = null;
        try {
            defaultLayer = dstDoc.layers[0];
        } catch (_) {}

        var srcLayers = srcDoc.layers.everyItem().getElements();
        for (i = 0; i < srcLayers.length; i++) {
            var sl = srcLayers[i];
            var dl = dstDoc.layers.itemByName(sl.name);

            if (!dl.isValid) {
                dl = dstDoc.layers.add({ name: sl.name });
            }

            try { dl.visible = sl.visible; } catch (_) {}
            try { dl.locked = false; } catch (_) {}
            try { dl.printable = sl.printable; } catch (_) {}
            try { dl.layerColor = sl.layerColor; } catch (_) {}
        }

        if (defaultLayer && defaultLayer.isValid) {
            try {
                if (srcDoc.layers.itemByName(defaultLayer.name).isValid === false) {
                    defaultLayer.remove();
                }
            } catch (_) {}
        }
    }

    function buildSinglePageMasters(srcDoc, dstDoc) {
        var map = {};
        var srcMasters = srcDoc.masterSpreads.everyItem().getElements();
        var i, p;

        for (i = 0; i < srcMasters.length; i++) {
            var sm = srcMasters[i];
            var smPages = sm.pages.everyItem().getElements();

            for (p = 0; p < smPages.length; p++) {
                var sp = smPages[p];
                var side = getPageSideCode(sp);
                var newPrefix = safeMasterPrefix(dstDoc, sm.namePrefix + side);
                var newBaseName = sm.baseName + " [" + sideLabel(side) + "]";

                var dm = dstDoc.masterSpreads.add();
                try { dm.namePrefix = newPrefix; } catch (_) {}
                try { dm.baseName = newBaseName; } catch (_) {}

                var dmp = dm.pages[0];

                copyPageSize(sp, dmp);
                copyMarginPreferences(sp, dmp);
                copyGuides(sp, dmp);

                var items = sp.pageItems.everyItem().getElements();
                for (var j = 0; j < items.length; j++) {
                    duplicateItemSafely(items[j], dmp, dstDoc);
                }

                map[sm.id + "_" + side] = dm;
            }
        }

        return map;
    }

    function safeMasterPrefix(doc, wantedPrefix) {
        var prefix = wantedPrefix;
        var n = 1;

        while (masterPrefixExists(doc, prefix)) {
            prefix = wantedPrefix + n;
            n++;
        }
        return prefix;
    }

    function masterPrefixExists(doc, prefix) {
        var masters = doc.masterSpreads.everyItem().getElements();
        for (var i = 0; i < masters.length; i++) {
            try {
                if (masters[i].namePrefix === prefix) return true;
            } catch (_) {}
        }
        return false;
    }

    function applyEquivalentMaster(srcPage, dstPage, masterMap) {
        try {
            var am = srcPage.appliedMaster;
            if (!am || !am.isValid) {
                dstPage.appliedMaster = NothingEnum.NOTHING;
                return;
            }

            var side = getPageSideCode(srcPage);
            var key = am.id + "_" + side;

            if (masterMap[key] && masterMap[key].isValid) {
                dstPage.appliedMaster = masterMap[key];
            } else {
                dstPage.appliedMaster = NothingEnum.NOTHING;
            }
        } catch (_) {
            try {
                dstPage.appliedMaster = NothingEnum.NOTHING;
            } catch (__){}
        }
    }

    function duplicateItemSafely(srcItem, dstPage, dstDoc) {
        try {
            var dstLayer = null;
            try {
                dstLayer = dstDoc.layers.itemByName(srcItem.itemLayer.name);
            } catch (_) {}

            var dup = srcItem.duplicate(dstPage);

            if (dstLayer && dstLayer.isValid) {
                try { dup.itemLayer = dstLayer; } catch (_) {}
            }
        } catch (_) {
            // Ignore unsupported/problematic items
        }
    }

    function copyPageSize(srcPage, dstPage) {
        try {
            var b = srcPage.bounds; // [y1, x1, y2, x2]
            var w = b[3] - b[1];
            var h = b[2] - b[0];

            dstPage.resize(
                CoordinateSpaces.INNER_COORDINATES,
                AnchorPoint.TOP_LEFT_ANCHOR,
                ResizeMethods.REPLACING_CURRENT_DIMENSIONS_WITH,
                [w, h]
            );
        } catch (_) {
            // Fallback: leave destination page size as document default
        }
    }

    function copyMarginPreferences(srcPage, dstPage) {
        try {
            dstPage.marginPreferences.top = srcPage.marginPreferences.top;
            dstPage.marginPreferences.bottom = srcPage.marginPreferences.bottom;
            dstPage.marginPreferences.left = srcPage.marginPreferences.left;
            dstPage.marginPreferences.right = srcPage.marginPreferences.right;

            try { dstPage.marginPreferences.columnCount = srcPage.marginPreferences.columnCount; } catch (_) {}
            try { dstPage.marginPreferences.columnGutter = srcPage.marginPreferences.columnGutter; } catch (_) {}
            try { dstPage.marginPreferences.columnsPositions = srcPage.marginPreferences.columnsPositions; } catch (_) {}
        } catch (_) {}
    }

    function copyGuides(srcPage, dstPage) {
        try {
            var guides = srcPage.guides.everyItem().getElements();
            for (var i = 0; i < guides.length; i++) {
                guides[i].duplicate(dstPage);
            }
        } catch (_) {}
    }

    function getPageSideCode(pg) {
        try {
            switch (pg.side) {
                case PageSideOptions.LEFT_HAND:
                    return "L";
                case PageSideOptions.RIGHT_HAND:
                    return "R";
                default:
                    return "S";
            }
        } catch (_) {
            return "S";
        }
    }

    function sideLabel(code) {
        if (code === "L") return "Left";
        if (code === "R") return "Right";
        return "Single";
    }

    function tryDeleteUnusedDefaultMaster(defaultMaster, dstDoc) {
        if (!defaultMaster || !defaultMaster.isValid) return;

        try {
            var used = false;
            var pages = dstDoc.pages.everyItem().getElements();

            for (var i = 0; i < pages.length; i++) {
                try {
                    if (pages[i].appliedMaster && pages[i].appliedMaster.isValid && pages[i].appliedMaster.id === defaultMaster.id) {
                        used = true;
                        break;
                    }
                } catch (_) {}
            }

            if (!used) {
                defaultMaster.remove();
            }
        } catch (_) {}
    }

})();
